//! Opt-in licensed/generation matrix; no personal-library discovery.
use crate::{
    imaging,
    safety_tests::{register, state},
    watermark,
};
use image::imageops::FilterType;
use std::{fs, path::Path};

#[test]
#[ignore = "Requires explicit MG_MOBILE_FIXTURES generated by scripts/qa/mobile-fixtures.swift"]
fn phone_gain_map_and_heic_render_sdr_with_reference_and_keep_originals() {
    let fixtures = std::env::var_os("MG_MOBILE_FIXTURES").expect("Explicit QA fixture directory");
    let fixtures = Path::new(&fixtures);
    let temp = tempfile::tempdir().unwrap();
    let base = temp.path().canonicalize().unwrap();
    let s = state(&base.join("runtime"));
    let mut results = Vec::new();
    let fixture_report: Vec<serde_json::Value> =
        serde_json::from_slice(&fs::read(fixtures.join("fixture-report.json")).unwrap()).unwrap();
    assert_eq!(fixture_report.len(), 11);
    for item in fixture_report {
        let name = item["name"].as_str().unwrap();
        let original = fs::read(fixtures.join(name)).unwrap();
        let source = base.join(name);
        fs::write(&source, &original).unwrap();
        let (folder, id) = register(&s, &source);
        s.allowed.lock().unwrap().insert(folder, base.clone());
        let reference = image::open(fixtures.join(format!("{name}.reference.png")))
            .unwrap()
            .to_rgb8();
        let options = watermark::Options {
            city: "测试城市".into(),
            ..Default::default()
        };
        let info = watermark::inspect(&original, &options).unwrap();
        assert_eq!((info.width, info.height), reference.dimensions());
        let rendered = watermark::render(&original, &options, None).unwrap();
        let mut outputs = vec![("watermark", rendered.jpeg)];
        for size in [480, 1600] {
            outputs.push((
                if size == 480 { "thumb" } else { "preview" },
                imaging::render(&s, &id, size).unwrap(),
            ));
        }
        let mut metrics = Vec::new();
        for (kind, bytes) in outputs {
            let actual = image::load_from_memory(&bytes).unwrap().to_rgb8();
            if kind == "watermark" {
                assert_eq!(actual.dimensions(), reference.dimensions());
            } else {
                assert!(actual.width() <= 1600 && actual.height() <= 1600);
            }
            assert!(
                (actual.width() as f64 / actual.height() as f64
                    - reference.width() as f64 / reference.height() as f64)
                    .abs()
                    < 0.005
            );
            let expected = image::imageops::resize(
                &reference,
                actual.width(),
                actual.height(),
                FilterType::Triangle,
            );
            let mut error = 0f64;
            let mut count = 0;
            // Stay outside caption bounds and edge-resampling differences.
            for y in (8..actual.height() * 4 / 5).step_by(7) {
                for x in (8..actual.width() - 8).step_by(7) {
                    let a = actual.get_pixel(x, y);
                    let b = expected.get_pixel(x, y);
                    for channel in 0..3 {
                        error += (f64::from(a[channel]) - f64::from(b[channel])).abs();
                        count += 1;
                    }
                }
            }
            let mae = error / count as f64;
            assert!(
                mae < 8.0,
                "{name} {kind} diverged from Core Image SDR reference: {mae}"
            );
            if let Ok(exif) =
                exif::Reader::new().read_from_container(&mut std::io::Cursor::new(&bytes))
            {
                assert!(
                    exif.get_field(exif::Tag::GPSLatitude, exif::In::PRIMARY)
                        .is_none()
                );
                assert!(
                    exif.get_field(exif::Tag::Model, exif::In::PRIMARY)
                        .is_none()
                );
            }
            metrics.push(serde_json::json!({"kind":kind,"width":actual.width(),"height":actual.height(),"sdrReferenceMAE":mae}));
        }
        assert_eq!(fs::read(source).unwrap(), original);
        assert_eq!(
            s.catalog
                .lock()
                .unwrap()
                .db
                .query_row("SELECT rating FROM assets WHERE id=?1", [&id], |r| r
                    .get::<_, Option<i32>>(0))
                .unwrap(),
            None
        );
        results.push(serde_json::json!({"name":name,"outputs":metrics}));
    }
    println!("MOBILE_SDR {}", serde_json::to_string(&results).unwrap());
}

#[test]
#[ignore = "Explicit generated HEIC samples via MG_MOBILE_FIXTURES"]
fn heic_scan_metadata_uses_pixel_dimensions_and_exif_date() {
    use crate::{grant, scan_directory};
    use std::sync::{Arc, Mutex};
    let input = Path::new(&std::env::var("MG_MOBILE_FIXTURES").unwrap()).join("02-sdr.heic");
    let temp = tempfile::tempdir().unwrap();
    let base = temp.path().canonicalize().unwrap();
    let sources = base.join("sources");
    fs::create_dir(&sources).unwrap();
    fs::copy(input, sources.join("phone.heic")).unwrap();
    let s = state(&base.join("runtime"));
    let f = grant(&s, sources.clone()).unwrap();
    let rows = Arc::new(Mutex::new(Vec::<crate::catalog::Asset>::new()));
    let copy = rows.clone();
    let channel = tauri::ipc::Channel::new(move |body| {
        if let tauri::ipc::InvokeResponseBody::Json(text) = body {
            let v: serde_json::Value = serde_json::from_str(&text).unwrap();
            if v["kind"] == "batch" {
                copy.lock().unwrap().extend(
                    serde_json::from_value::<Vec<crate::catalog::Asset>>(v["items"].clone())
                        .unwrap(),
                );
            }
        }
        Ok(())
    });
    scan_directory(&s, &sources, f.id, 0, &channel).unwrap();
    let rows = rows.lock().unwrap();
    assert_eq!(rows.len(), 1);
    assert_eq!((rows[0].width, rows[0].height), (3024, 4032));
    assert!(rows[0].captured.as_ref().unwrap().contains("2024:12:07"));
}
